    "scenario": "平日・晴れ・高温条件（1.5倍ロジック適用）",
    "input_data": {
      "date": "2024-05-15",
      "day_of_week": "Wednesday",
      "weather_forecast": {
        "condition": "Sunny",
        "precipitation_probability": 10,
        "max_temperature": 28
      },
      "current_inventory": {
        "flour_kg": 50,
        "butter_kg": 10
      },
